import { expect, test, uniqueName } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;

async function waitForExtraction(
  member: import("@playwright/test").APIRequestContext,
  documentId: string,
): Promise<{ id: string }> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const doc = await member.get(`/api/documents/${documentId}`);
    expect(doc.status()).toBe(200);
    const body = await doc.json();
    if (body.status === "extracted") {
      const ext = await member.get(`/api/documents/${documentId}/extraction`);
      expect(ext.status()).toBe(200);
      return ext.json();
    }
    expect(body.status, "document must not fail extraction").not.toBe("failed");
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`document ${documentId} was not extracted in time`);
}

test.describe("review vendors", () => {
  test(
    "approving every extraction approves the vendor",
    { tag: "@REV-05" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor, uploads three documents, and submits it.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const suffix = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV-05 Vendor"),
          category: "services",
          contact_email: `rev05-${suffix}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const documentIds: string[] = [];
      for (const kind of KINDS) {
        const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}-${suffix}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 ${kind} ${suffix}`),
            },
          },
        });
        expect(upload.status()).toBe(201);
        documentIds.push((await upload.json()).id);
      }

      const extractionIds: string[] = [];
      for (const documentId of documentIds) {
        const extraction = await waitForExtraction(member, documentId);
        extractionIds.push(extraction.id);
      }

      const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
      expect(submit.status()).toBe(200);
      expect((await submit.json()).status).toBe("in_review");

      // Act: the reviewer approves all three extractions.
      for (const extractionId of extractionIds) {
        const decision = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
          data: { decision: "approve" },
        });
        expect(decision.status()).toBe(200);
        expect((await decision.json()).status).toBe("approved");
      }

      // Assert: the vendor is approved.
      const vendorResponse = await reviewer.get(`/api/vendors/${vendor.id}`);
      expect(vendorResponse.status()).toBe(200);
      expect((await vendorResponse.json()).status).toBe("approved");

      // Assert: the audit trail records vendor.approved.
      const auditResponse = await reviewer.get(`/api/vendors/${vendor.id}/audit`);
      expect(auditResponse.status()).toBe(200);
      const audit = await auditResponse.json();
      const actions = (audit.items as { action: string }[]).map((event) => event.action);
      expect(actions).toContain("vendor.approved");
    },
  );
});
